describe('Dropdown Menu Keyboard Navigation', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="dropdown-trigger"]').as('dropdownTrigger');
    cy.get('[data-testid="dropdown-menu"]').as('dropdownMenu');
  });

  it('should navigate dropdown items using arrow keys', () => {
    cy.get('@dropdownTrigger').click();
    cy.get('@dropdownMenu').should('be.visible');

    cy.get('[data-testid="dropdown-item"]').first().should('have.focus');

    cy.get('@dropdownMenu').type('{downarrow}');
    cy.get('[data-testid="dropdown-item"]').eq(1).should('have.focus');

    cy.get('@dropdownMenu').type('{downarrow}');
    cy.get('[data-testid="dropdown-item"]').eq(2).should('have.focus');

    cy.get('@dropdownMenu').type('{uparrow}');
    cy.get('[data-testid="dropdown-item"]').eq(1).should('have.focus');

    cy.get('@dropdownMenu').type('{uparrow}');
    cy.get('[data-testid="dropdown-item"]').first().should('have.focus');
  });

  it('should wrap around when navigating past last item with down arrow', () => {
    cy.get('@dropdownTrigger').click();
    cy.get('@dropdownMenu').should('be.visible');

    const itemCount = cy.get('[data-testid="dropdown-item"]').its('length');

    cy.get('[data-testid="dropdown-item"]').last().focus();
    cy.get('@dropdownMenu').type('{downarrow}');
    cy.get('[data-testid="dropdown-item"]').first().should('have.focus');
  });

  it('should wrap around when navigating past first item with up arrow', () => {
    cy.get('@dropdownTrigger').click();
    cy.get('@dropdownMenu').should('be.visible');

    cy.get('[data-testid="dropdown-item"]').first().focus();
    cy.get('@dropdownMenu').type('{uparrow}');
    cy.get('[data-testid="dropdown-item"]').last().should('have.focus');
  });

  it('should select item with Enter key after navigation', () => {
    cy.get('@dropdownTrigger').click();
    cy.get('@dropdownMenu').should('be.visible');

    cy.get('@dropdownMenu').type('{downarrow}');
    cy.get('@dropdownMenu').type('{downarrow}');
    cy.get('[data-testid="dropdown-item"]').eq(2).should('have.focus');

    cy.get('@dropdownMenu').type('{enter}');
    cy.get('[data-testid="dropdown-item"]').eq(2).should('have.attr', 'aria-selected', 'true');
    cy.get('@dropdownMenu').should('not.be.visible');
  });

  it('should close dropdown with Escape key', () => {
    cy.get('@dropdownTrigger').click();
    cy.get('@dropdownMenu').should('be.visible');

    cy.get('@dropdownMenu').type('{downarrow}');
    cy.get('@dropdownMenu').type('{esc}');
    cy.get('@dropdownMenu').should('not.be.visible');
  });
});
